<script setup lang="ts">
import{ref}from'vue';import{useFollowupPlanPage}from'./use-followup-plan-page';
const props=defineProps<{account:any;clinicId:string;planId:string;read:(p:string,signal:AbortSignal)=>Promise<any>}>(),emit=defineEmits(['invalidated']),opened=ref(false),model=useFollowupPlanPage({account:()=>props.account,clinic:()=>props.clinicId,context:()=>String(opened.value),planId:()=>props.planId,read:(p,s)=>props.read(p,s),invalidated:s=>{if(s===401||s===403)emit('invalidated',s);}});
function toggle(e:Event){opened.value=(e.target as HTMLDetailsElement).open;if(opened.value)void model.load();}
const full=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'无固定终点';
</script>
<template><details class="care-history" @toggle="toggle"><summary>查看该方案各版本及采用节点</summary><template v-if="opened"><p v-if="model.error.value" class="b-alert error" role="alert">{{model.error.value}}</p><button v-if="model.error.value" type="button" class="b-button outline small" :disabled="model.loading.value" @click="model.load()">重新读取方案版本</button><p v-if="model.loading.value&&!model.asOf.value" class="b-help" role="status">正在读取方案版本…</p><p v-if="model.asOf.value" class="b-help">已显示 {{model.items.value.length}} / {{model.total.value}} 个版本</p><div v-for="v in model.items.value" :key="v.plan_version_id"><p>第 {{v.version_no}} 版 · {{full(v.effective_from)}} — {{full(v.effective_to)}}</p><p v-for="n in v.nodes" :key="n.node_id">{{n.time_arrangement}} · {{n.contact_content}}<br/>{{n.clinical_purpose}}</p></div><button v-if="model.next.value" type="button" class="b-button outline small" :disabled="model.loading.value" @click="model.load(true)">继续加载方案版本</button></template></details></template>
